-- GKUC historical import PRE-FLIGHT ONLY. No business-table INSERT/UPDATE/DELETE/ALTER.

-- Select the existing application database in phpMyAdmin first. MySQL 8+ / compatible MariaDB.

-- Source files were not repaired or changed. This script is NOT the final import.

SET NAMES utf8mb4;

SELECT DATABASE() selected_database, VERSION() server_version, 'PRE-FLIGHT ONLY - NO IMPORT' mode;

DROP TEMPORARY TABLE IF EXISTS tmp_gkuc_20261031_source;

CREATE TEMPORARY TABLE tmp_gkuc_20261031_source (sheet_name VARCHAR(40), excel_row INT, source_code VARCHAR(120), link_code VARCHAR(120), source_name TEXT, company_name VARCHAR(120), original_reference VARCHAR(180), payload LONGTEXT) ENGINE=InnoDB;



















START TRANSACTION READ ONLY;

-- A: Source counts; these must be 17/17/23/23/23/984.

SELECT sheet_name,COUNT(*) source_rows FROM tmp_gkuc_20261031_source GROUP BY sheet_name;

-- B: Target schema and engines. Missing columns/older schema may stop later SELECTs; no business data is changed.

SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('clients','projects','boqs','boq_items','employees','companies','historical_import_links','project_team');

SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('clients','projects','boqs','boq_items','project_team') ORDER BY TABLE_NAME,ORDINAL_POSITION;

-- C: Matching client candidates; no automatic merge and no existing fields overwritten.

SELECT s.excel_row,s.source_code,s.source_name,c.id existing_id,c.name existing_name,c.type,c.active FROM tmp_gkuc_20261031_source s LEFT JOIN clients c ON REGEXP_REPLACE(LOWER(TRIM(c.name)),'[[:space:]]+',' ')=REGEXP_REPLACE(LOWER(TRIM(s.source_name)),'[[:space:]]+',' ') WHERE s.sheet_name='Clients' ORDER BY s.excel_row,c.id;

-- D: All company IDs; do not assume Ready mix uses a particular ID.

SELECT id,code,name,active FROM companies ORDER BY id;

-- E: Exact normalized project-name candidates across every company. Shortened/alternate existing names need manual matching.

SELECT s.excel_row,s.source_code,s.company_name,s.source_name,p.id existing_id,p.name existing_name,p.company_id,p.client_id,p.stage,p.health,p.progress,p.budget FROM tmp_gkuc_20261031_source s LEFT JOIN projects p ON REGEXP_REPLACE(LOWER(TRIM(p.name)),'[[:space:]]+',' ')=REGEXP_REPLACE(LOWER(TRIM(s.source_name)),'[[:space:]]+',' ') WHERE s.sheet_name='Projects' ORDER BY s.excel_row,p.id;

-- F: Existing BOQ-reference candidates; names/references are suggestions only, not an authorization to append items.

SELECT s.excel_row,s.source_code,s.link_code project_code,s.original_reference,b.id existing_id,b.project_id,b.reference,b.title,b.version,b.status,b.total FROM tmp_gkuc_20261031_source s LEFT JOIN boqs b ON LOWER(TRIM(b.reference))=LOWER(TRIM(s.original_reference)) OR REGEXP_REPLACE(LOWER(TRIM(b.title)),'[[:space:]]+',' ')=REGEXP_REPLACE(LOWER(TRIM(s.source_name)),'[[:space:]]+',' ') WHERE s.sheet_name='BOQ Headers' ORDER BY s.excel_row,b.id;

-- G: Resolve the two source employee codes against actual employees. All duplicate candidates remain visible.

SELECT id,code,name,status FROM employees WHERE code IN ('EMP-001','EMP-0001') ORDER BY id;

-- H: Existing durable import mappings. Review collisions before inserting anything.

SELECT s.sheet_name,s.excel_row,s.source_code,l.kind,l.target_id,l.batch_id FROM tmp_gkuc_20261031_source s LEFT JOIN historical_import_links l ON l.source_code=s.source_code AND l.kind=CASE s.sheet_name WHEN 'Clients' THEN 'clients' WHEN 'Projects' THEN 'projects' ELSE 'boqs' END WHERE s.sheet_name IN ('Clients','Projects','BOQ Headers') ORDER BY s.sheet_name,s.excel_row;

-- I: Full target project/reference inventories for manual alternate-name duplicate review.

SELECT p.id,p.name,p.company_id,p.client_id,p.stage,p.health,p.progress,p.budget FROM projects p ORDER BY p.company_id,p.id;

SELECT b.id,b.project_id,b.reference,b.title,b.version,b.status,b.total,COUNT(i.id) item_count FROM boqs b LEFT JOIN boq_items i ON i.boq_id=b.id GROUP BY b.id,b.project_id,b.reference,b.title,b.version,b.status,b.total ORDER BY b.id;

-- Temporary source rows are available only in this SQL session and are now removed.

ROLLBACK;

DROP TEMPORARY TABLE tmp_gkuc_20261031_source;

SELECT 'PRE-FLIGHT COMPLETE. No application records imported or modified.' result;
